      "text": "मैं seller का नाम और city directly share नहीं कर सकती पर मैं आपको best seller से connect करा दूंगी।"
    },
    {
      "i": 31,
      "speaker": "bot",
      "text": "क्या मैं call transfer करूं?"
    },
    {
      "i": 32,
      "speaker": "caller",
      "text": "कौन क्यों नहीं share कर सकती क्योंकि बात करेंगे तो पता नहीं चल जाएगा।"
    },
    {
      "i": 33,
      "speaker": "caller",
      "text": "आप ही बता दें तो हम बताएंगे कि यहां उनसे connect करना है या नहीं करना।"
    },
    {
      "i": 34,
      "speaker": "bot",
      "text": "मैं समझ सकती हूं पर security कारणों से मैं details share नहीं कर सकती।"
    },
    {
      "i": 35,
      "speaker": "bot",
      "text": "आप connect होकर देख लीजिए क्या मैं transfer करूं?"
    },
    {
      "i": 36,
      "speaker": "caller",
      "text": "आप AI हैं या actual?"
    },
    {
      "i": 37,
      "speaker": "bot",
      "text": "मैं आपकी मदद के लिए यहां हूं बस आप बताइए कि क्या मैं आपकी call transfer कर दूं?"
    },
    {
      "i": 38,
      "speaker": "caller",
      "text": "आप AI हैं ना बाकी AI से बाहर चल के सोचिए।"
    },
    {
      "i": 39,
      "speaker": "bot",
      "text": "मैं बस आपकी मदद करना चाहती हूं।"
    },
    {
      "i": 40,
      "speaker": "bot",
      "text": "क्या मैं आपकी call seller को transfer कर दूं?"
    },
    {
      "i": 41,
      "speaker": "caller",
      "text": "कौन से seller को transfer करना है?"
    },
    {
      "i": 42,
      "speaker": "bot",
      "text": "मैं आपको सबसे बेहतरीन और verified seller से connect करवाऊंगी।"
    },
    {
      "i": 43,
      "speaker": "bot",
      "text": "क्या मैं call transfer कर दूं?"
    },
    {
      "i": 44,
      "speaker": "caller",
      "text": "बेहतरीन।"
    },
    {
      "i": 45,
      "speaker": "caller",
      "text": "answer कर दीजिए कोई दिक्कत नहीं।"
    },
    {
      "i": 46,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 47,
      "speaker": "bot",
      "text": "मैं आपकी call transfer कर रही हूं और बाकी sellers की details आपको WhatsApp पे भेज दी जाएंगी।"
    },
    {
      "i": 48,
      "speaker": "bot",
      "text": "Please line पे बने रहें।"
    }
